def main():
    for front, back, tags in CARDS:
        DECK.add_note(genanki.Note(model=MODEL, fields=[front, back], tags=tags))
    genanki.Package(DECK).write_to_file("simulacion-2-familiar-orl.apkg")
    with open("simulacion-2-familiar-orl.tsv", "w", encoding="utf-8") as f:
        for front, back, tags in CARDS:
            f.write(f"{front}\t{back}\t{' '.join(tags)}\n")
    print(f"Listo: {len(CARDS)} tarjetas -> simulacion-2-familiar-orl.apkg + .tsv")


if __name__ == "__main__":
    main()
